public abstract class AbstractConfigurationFunctionTestCase extends AbstractFunctionTestCase {
    protected abstract Expression buildWithConfiguration(Source source, List<Expression> args, EsqlConfiguration configuration);

    @Override
    protected Expression build(Source source, List<Expression> args) {
        return buildWithConfiguration(source, args, EsqlTestUtils.TEST_CFG);
    }

    static EsqlConfiguration randomConfiguration() {
        // TODO: Randomize the query and maybe the pragmas.
        return new EsqlConfiguration(
            randomZone(),
            randomLocale(random()),
            randomBoolean() ? null : randomAlphaOfLength(randomInt(64)),
            randomBoolean() ? null : randomAlphaOfLength(randomInt(64)),
            QueryPragmas.EMPTY,
            EsqlPlugin.QUERY_RESULT_TRUNCATION_MAX_SIZE.getDefault(Settings.EMPTY),
            EsqlPlugin.QUERY_RESULT_TRUNCATION_DEFAULT_SIZE.getDefault(Settings.EMPTY),
            StringUtils.EMPTY,
            randomBoolean()
        );
    }

    public void testSerializationWithConfig() {
        EsqlConfiguration config = randomConfiguration();
        Expression expr = buildWithConfiguration(testCase.getSource(), testCase.getDataAsFields(), config);

        assertSerialization(expr);

        EsqlConfiguration differentConfig;
        do {
            differentConfig = randomConfiguration();
        } while (config.equals(differentConfig));

        Expression differentExpr = buildWithConfiguration(testCase.getSource(), testCase.getDataAsFields(), differentConfig);
        assertFalse(expr.equals(differentExpr));
    }
}

public abstract class RationalUnaryPredicate extends UnaryScalarFunction {
    public RationalUnaryPredicate(Source source, Expression field) {
        super(source, field);
    }

    @Override
    protected final TypeResolution resolveType() {
        if (childrenResolved() == false) {
            return new TypeResolution("Unresolved children");
        }

        return isType(field(), DataType::isRational, sourceText(), null, DataTypes.DOUBLE.typeName());
    }

    @Override
    public final DataType dataType() {
        return DataTypes.BOOLEAN;
    }
}

public static void assertSerialization(Expression expression, EsqlConfiguration configuration) {
        Expression deserExpression = serializeDeserialize(
            expression,
            PlanStreamOutput::writeExpression,
            PlanStreamInput::readExpression,
            configuration
        );
        EqualsHashCodeTestUtils.checkEqualsAndHashCode(expression, unused -> deserExpression);
    }

public static void assertSerialization(PhysicalPlan plan, EsqlConfiguration configuration) {
        var deserPlan = serializeDeserialize(
            plan,
            PlanStreamOutput::writePhysicalPlanNode,
            PlanStreamInput::readPhysicalPlanNode,
            configuration
        );
        EqualsHashCodeTestUtils.checkEqualsAndHashCode(plan, unused -> deserPlan);
    }

